  strategyGuide: { badge: 'Routing and strategy', title: 'Key strategies', description: 'Learn about Niffler logging, intelligent routing modes, and service-limit policies.', loggingTitle: '1. Request-body logging', loggingText: 'Change request-body detail levels in system settings for debugging and auditing.', logLevel: 'Log level', logContent: 'Recorded content', basicRequest: 'Basic request data (IP, model, latency, tokens, etc.)', headersRequest: 'Base + request headers', fullPayload: 'Headers + full request and response payloads', routingTitle: '2. Routing modes', providerFirst: 'Provider first: schedule according to provider order.', keyFirst: 'Key first: ignore provider hierarchy and schedule all available keys by priority.', cacheAffinity: 'Cache affinity: route the same user to the provider/node that handled the previous request when possible.', loadBalance: 'Load balancing: distribute traffic evenly among nodes at the same priority.', fixedOrder: 'Fixed order: remove randomness and dynamic adjustment; try keys in a fixed order.', failover: 'Failover: when a request fails, switch to the next available backup node and retry according to policy.', rateLimitTitle: '3. Access limits', rateLimitText: 'The system supports rate limits across multiple dimensions to prevent abuse and keep the service stable.', cleanupTitle: '4. Request-body cleanup', cleanupText: 'Automatic cleanup and compression save database space and improve query performance by periodically separating and removing historical request details.', tasksTitle: '5. Scheduled tasks', tasksText: 'Built-in scheduled tasks synchronize models, clean caches, monitor balances, and aggregate statistics.' },
  advancedGuide: { badge: 'Advanced usage', title: 'Advanced features', description: 'Unlock Niffler custom request edits, intelligent conversion, and advanced configuration.', formatTitle: '1. Format conversion', formatText: 'Format conversion lets non-native requests pass through the Gateway in the downstream format. Conversion can happen at several levels:', globalConversion: 'Global conversion', globalConversionText: 'Default conversion rules enabled or disabled system-wide.', providerConversion: 'Provider conversion', providerConversionText: 'Format conversion settings applied to all requests for a specific provider.', endpointConversion: 'Endpoint conversion', endpointConversionText: 'Fine-grained conversion support for one endpoint.', streamPolicyTitle: '2. Force non-streaming or streaming upstream', streamPolicyText: 'Some providers behave differently in streaming and non-streaming modes. This forces a chosen mode upstream while restoring the user-requested mode at the frontend.', headerBodyTitle: '3. Edit request headers and body', headerBodyText: 'Add rules in endpoint settings and use conditions and actions such as Delete, Set, and Insert to modify upstream headers or JSON payloads dynamically.', modelMappingTitle: '4. Model mapping', modelMappingText: 'Resolve differences between provider-specific and platform-standard model names by translating the unified request model to the upstream model.', regexTitle: '5. Regex mapping', modelPermissions: 'Model permissions', modelPermissionsText: 'Use regular expressions to match a model class and grant access in bulk.', autoFetch: 'Automatically fetch upstream models', autoFetchText: 'Apply regex filtering and cleanup to fetched models to quickly import a matching standard model list.', balanceTitle: '6. Balance monitoring', balanceText: 'Fetch and record remaining quota from provider APIs or common aggregators, then alert or disable when it falls below a threshold.', configTitle: '7. Configuration import/export', configText: 'Export unified models, provider endpoints, and gateway routing policies to JSON and migrate them into another deployment.', lockKeyTitle: '8. Lock user keys', lockKeyText: 'When malicious use, anomalous calls, or frequent errors are detected, administrators can temporarily or permanently lock a key to block the source.' },
